-- Synthetic local-only profile fixture; never an application migration.
CREATE TABLE IF NOT EXISTS clients(Id INT PRIMARY KEY,Name VARCHAR(180),IsActive BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS employees(Id INT PRIMARY KEY,ClientId INT NOT NULL,EmployeeCode VARCHAR(80),FirstName VARCHAR(100),LastName VARCHAR(100),Gender VARCHAR(30) NOT NULL DEFAULT '',IsActive BOOLEAN NOT NULL DEFAULT TRUE,WorkLocationId INT NOT NULL DEFAULT 0,ReportingManagerId INT NOT NULL DEFAULT 0,ReportingManagerUserId INT NULL,WorkEmail VARCHAR(190) NOT NULL DEFAULT '',Department VARCHAR(100) NOT NULL DEFAULT '',Designation VARCHAR(100) NOT NULL DEFAULT '',DateOfJoining VARCHAR(30) NOT NULL DEFAULT '',AnnualCtc DECIMAL(18,4) NOT NULL DEFAULT 0,SalaryStructureId VARCHAR(100) NOT NULL DEFAULT '',SalaryJson JSON NULL);
CREATE TABLE IF NOT EXISTS worklocations(Id INT PRIMARY KEY,Name VARCHAR(190));
CREATE TABLE IF NOT EXISTS authusers(Id INT PRIMARY KEY,DisplayName VARCHAR(190) NOT NULL DEFAULT '',ClientId INT NULL,EmployeeId INT NULL,IsActive BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS travel_expense_client_settings(ClientId INT PRIMARY KEY,IsEnabled BOOLEAN,EffectiveFrom DATE NULL,EffectiveTo DATE NULL);
CREATE TABLE IF NOT EXISTS attendance_geo_fence_rules(id INT PRIMARY KEY AUTO_INCREMENT,client_id INT,name VARCHAR(180),scope_type VARCHAR(40),work_location_id INT NULL,latitude DECIMAL(10,7),longitude DECIMAL(10,7),radius_meters INT DEFAULT 100,gps_tolerance_meters INT DEFAULT 30,strictness VARCHAR(60) DEFAULT 'Block outside fence',allow_check_in BOOLEAN DEFAULT TRUE,allow_check_out BOOLEAN DEFAULT TRUE,effective_from DATE,effective_to DATE NULL,is_active BOOLEAN DEFAULT TRUE,priority INT DEFAULT 20);
CREATE TABLE IF NOT EXISTS attendance_geo_fence_rule_employees(geo_fence_rule_id INT,employee_id INT);
CREATE TABLE IF NOT EXISTS employee_form_bindings(Id BIGINT PRIMARY KEY AUTO_INCREMENT,ClientId INT,FormDefinitionId BIGINT,InfotypeCode VARCHAR(30),IsRequired BOOLEAN,DisplayOrder INT,IsActive BOOLEAN);
CREATE TABLE IF NOT EXISTS form_definitions(Id BIGINT PRIMARY KEY,ClientId INT,ModuleCode VARCHAR(80),EntityType VARCHAR(80),Status VARCHAR(30),CurrentPublishedVersionId BIGINT,FormCode VARCHAR(80),FormName VARCHAR(190),PurposeCode VARCHAR(80));
CREATE TABLE IF NOT EXISTS form_versions(Id BIGINT PRIMARY KEY,VersionNumber INT,Status VARCHAR(30));
CREATE TABLE IF NOT EXISTS employee_it0002_personal_data(Id BIGINT PRIMARY KEY AUTO_INCREMENT,EmployeeId INT,ClientId INT,ActionType VARCHAR(80),EffectiveFrom DATE,EffectiveTo DATE NULL,Status VARCHAR(30),FirstName VARCHAR(100),LastName VARCHAR(100),Gender VARCHAR(30),DateOfBirth VARCHAR(30),Mobile VARCHAR(50),PanNumber VARCHAR(50),AadhaarNumber VARCHAR(50),UanNumber VARCHAR(50),EsicNumber VARCHAR(50),ChangeReason VARCHAR(500),CreatedBy VARCHAR(190));
CREATE TABLE IF NOT EXISTS employee_it0006_addresses(Id BIGINT PRIMARY KEY AUTO_INCREMENT,EmployeeId INT,ClientId INT,ActionType VARCHAR(80),EffectiveFrom DATE,EffectiveTo DATE NULL,Status VARCHAR(30),Address VARCHAR(800),CorrespondenceAddress VARCHAR(800),PermanentAddress VARCHAR(800),ChangeReason VARCHAR(500),CreatedBy VARCHAR(190));
CREATE TABLE IF NOT EXISTS employee_it0009_bank_details(Id BIGINT PRIMARY KEY AUTO_INCREMENT,EmployeeId INT,ClientId INT,ActionType VARCHAR(80),EffectiveFrom DATE,EffectiveTo DATE NULL,Status VARCHAR(30),BankName VARCHAR(160),BankAccountNo VARCHAR(100),IfscCode VARCHAR(40),PaymentMode VARCHAR(60),ChangeReason VARCHAR(500),CreatedBy VARCHAR(190));
CREATE TABLE IF NOT EXISTS ResourceStates(Id BIGINT PRIMARY KEY AUTO_INCREMENT,ResourceType VARCHAR(100),ResourceId VARCHAR(120),CurrentState VARCHAR(60),WorkflowInstanceId BIGINT NULL,CreatedBy INT NOT NULL DEFAULT 0,ModifiedBy INT NOT NULL DEFAULT 0,CreatedOn DATETIME DEFAULT CURRENT_TIMESTAMP,ModifiedOn DATETIME DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY UX_ResourceStates_Resource(ResourceType,ResourceId));
CREATE TABLE IF NOT EXISTS workflowmasters(Id INT PRIMARY KEY AUTO_INCREMENT,ClientId INT NULL,Code VARCHAR(80),Name VARCHAR(180),ResourceType VARCHAR(100),IsActive BOOLEAN);
CREATE TABLE IF NOT EXISTS workflowstages(Id INT PRIMARY KEY AUTO_INCREMENT,WorkflowId INT,StageOrder INT,Name VARCHAR(180),ApproverType VARCHAR(40),ApproverUserId INT NULL);
CREATE TABLE IF NOT EXISTS workflowinstances(Id BIGINT PRIMARY KEY AUTO_INCREMENT,WorkflowId INT,ResourceType VARCHAR(100),ResourceId VARCHAR(120),RequestorUserId INT,PayloadJson JSON,Status VARCHAR(30) NOT NULL DEFAULT 'Pending',CreatedAt DATETIME DEFAULT CURRENT_TIMESTAMP,CompletedAt DATETIME NULL);
CREATE TABLE IF NOT EXISTS workflowtasks(Id BIGINT PRIMARY KEY AUTO_INCREMENT,InstanceId BIGINT,StageId INT,ApproverUserId INT,Status VARCHAR(30) NOT NULL DEFAULT 'Pending',ActionedAt DATETIME NULL,Comment VARCHAR(1000) NULL);
CREATE TABLE IF NOT EXISTS workflowhistory(Id BIGINT PRIMARY KEY AUTO_INCREMENT,InstanceId BIGINT,TaskId BIGINT NULL,Action VARCHAR(30),ActorUserId INT,Comment VARCHAR(1000) NULL,CreatedAt DATETIME DEFAULT CURRENT_TIMESTAMP);
